const SEASONAL_BANNER_ENABLED = true
function applyCatalogueDiscount(priceEur) {
  if (priceEur == null || !isCatalogueDiscountActive()) return priceEur
  return Number((Number(priceEur) * (1 - CATALOGUE_DISCOUNT_PCT / 100)).toFixed(2))
}
// Public catalogue small-order model: orders of €49–99.99 ship at a flat zone fee;
// €100+ keeps free shipping. Countries with exclusive distributors (Italy, France,
// Bulgaria, Greece) and any country not listed below keep the €100 minimum.
// B2B orders must keep the full €100 free-shipping threshold even when promotional
// pricing or seasonal banners are active.
const FREE_SHIPPING_EUR = 100
function getFreeShippingEur() {
  return FREE_SHIPPING_EUR
}
const SMALL_ORDER_MIN_EUR = 49
const SMALL_ORDER_SHIPPING_ZONES = [
  { feeEur: 15, countries: ['Austria', 'Germany', 'Hungary', 'Belgium', 'Netherlands', 'Poland', 'Slovakia', 'Slovenia', 'Croatia', 'Czech Republic'] },
  { feeEur: 22, countries: ['Denmark', 'Spain', 'Luxembourg', 'Estonia', 'Ireland', 'Latvia', 'Lithuania', 'Portugal', 'Finland', 'Sweden', 'Norway', 'Switzerland', 'United Kingdom'] },
]
const DISTRIBUTOR_COUNTRY_HANDOFF = {
  Italy: { url: 'https://www.gelitup.it', label: 'GEL.IT.UP Italy' },
  Bulgaria: { url: 'https://gelitup.bg', label: 'GEL.IT.UP Bulgaria' },
}
function getDistributorCountryHandoff(country) {
  const normalized = String(country || '').trim().toLowerCase()
  if (!normalized || normalized === 'greece') return null
  return Object.entries(DISTRIBUTOR_COUNTRY_HANDOFF).find(([name]) => name.toLowerCase() === normalized)?.[1] || null
}
function getSmallOrderShippingFee(country) {
  const name = String(country || '').trim().toLowerCase()
  if (!name) return null
  for (const zone of SMALL_ORDER_SHIPPING_ZONES) {
    if (zone.countries.some(c => c.toLowerCase() === name)) return zone.feeEur
  }
  return null
}
const B2B_PRICE_MULTIPLIER = 1.2
const PERFECT_SHAPE_TOP_COAT_UPLIFT = 1.06
function isPerfectShapeTopCoatProduct(name, sku) {
  const normalizedName = String(name || '').toLowerCase()
  const normalizedSku = String(sku || '').toLowerCase()
  return normalizedName.includes('top coat perfect shape')
    || normalizedName.includes('perfect shape top coat')
    || normalizedSku.includes('nwpt15')
}
function getAdjustedB2bBasePrice(name, sku, rawPrice) {
  const numericPrice = Number(rawPrice)
  if (!Number.isFinite(numericPrice) || numericPrice <= 0) return null
  return isPerfectShapeTopCoatProduct(name, sku)
    ? numericPrice * PERFECT_SHAPE_TOP_COAT_UPLIFT
    : numericPrice
}
function isMarkupExemptCuticleProduct(name) {
  // Scented cuticle oil & scrub range (e.g. "Cooling Coconut Cuticle Oil 5ml -HTF",
  // "Almond Cuticle Scrub Remover 100ml -HTF"). Their price-list values are already the
  // final retail prices, so the standard 1.2x B2B markup must not be applied.
  const normalizedName = String(name || '').toLowerCase()
  if (!/cuticle\s+(oil|scrub)/.test(normalizedName)) return false
  return /\d+\s*ml\b/.test(normalizedName)
}
