/** Fire-and-forget: record a login problem in Supabase and send a real-time email alert to admin. */
function logLoginIssue(email, issueType, message) {
  if (!hasSupabaseConfig || !supabase || !email) return
  const payload = { email: String(email).toLowerCase().trim(), issue_type: issueType, message: String(message || '').slice(0, 500) }

  // Write to Supabase (visible in the admin Login Issues tab)
  supabase.from('b2b_login_issues').insert(payload).then(() => {}).catch(() => {})

  // Send real-time email to admin via Netlify function
  fetch('/.netlify/functions/notify-admin', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email: payload.email, issueType, message: payload.message }),
  }).catch(() => {})
}

/**
 * Returns true if a Supabase signUp result indicates the email already belongs
 * to an existing account.  When email obfuscation is enabled Supabase returns a
 * user object with an empty `identities` array rather than an error.
 */
function isExistingUserSignUpResult(signUpResult) {
  const user = signUpResult?.data?.user
  if (!user) return false
  return Array.isArray(user.identities) && user.identities.length === 0
}

/**
 * Returns true if the Supabase signUp response includes an active session,
 * meaning the user was signed in immediately (email confirmation disabled).
 */
function hasActiveSignUpSession(signUpResult) {
  return Boolean(signUpResult?.data?.session)
}

function resolveVatTreatment(country) {
  return COUNTRY_VAT_TREATMENT[country] || 'export_exempt'
}

function getVatTreatmentLabel(treatment, country) {
  switch (treatment) {
    case 'reverse_charge':
      return { pct: 0, label: '0% - VAT Reverse Charge (EU B2B, Art. 44 Directive 2006/112/EC)', note: 'The customer is liable to account for VAT in their country of establishment.' }
    case 'domestic_bg':
      return { pct: 0, label: '0% - VAT Reverse Charge (EU B2B)', note: 'B2B cross-border supply. The customer is liable to account for VAT in their country of establishment.' }
    case 'domestic_gr':
      return { pct: 0, label: '0% - VAT Reverse Charge (EU B2B)', note: 'B2B cross-border supply. The customer is liable to account for VAT in their country of establishment.' }
    case 'export_exempt':
    default:
      return { pct: 0, label: '0% - Zero-rated Export (outside EU)', note: `Goods exported outside the EU. VAT exempt under export provisions. Buyer may be subject to local import duties in ${country || 'their country'}.` }
  }
}

// Returns null if valid, or an error string if the VAT prefix is wrong for the country
function validateVatPrefix(vatNumber, country) {
  const prefix = COUNTRY_VAT_PREFIX[country]
  if (!prefix) return null
  const vat = String(vatNumber || '').trim().toUpperCase().replace(/[\s\-\.]/g, '')
  if (!vat) return null
  if (!vat.startsWith(prefix.toUpperCase())) {
    return `VAT number for ${country} must start with ${prefix} (e.g. ${prefix}123456789)`
  }
  return null
}

