const SHOW_SERVICE_FLOW_SUBCATEGORY_MENU = false
const CATALOGUE_RESULTS_ANCHOR_ID = 'catalogue-results-anchor'

function withCountryDialCode(phoneValue = '', country = '') {
  const dialCode = COUNTRY_DIAL_CODES[country] || ''
  const current = String(phoneValue || '').trim()
  if (!dialCode) return current
  if (!current) return `${dialCode} `
  if (current.startsWith('+')) return current
  return `${dialCode} ${current}`
}

function extractTaggedValue(notesValue, tagName) {
  const notes = String(notesValue || '')
  const match = notes.match(new RegExp(`\\[${tagName}:([^\\]]+)\\]`, 'i'))
  return String(match?.[1] || '').trim().toLowerCase()
}

function getApplicationTypeFromRecord(record) {
  const explicit = String(record?.application_type || '').trim().toLowerCase()
  const tagged = extractTaggedValue(record?.notes, 'APPLICATION_TYPE')
  const tier = String(record?.distributor_tier || '').trim().toLowerCase()

  if (explicit === 'distributor' || tagged === 'distributor' || tier) return 'distributor'
  if (explicit) return explicit
  if (tagged) return tagged

  return 'b2b_order'
}

function getOrderProfileFromRecord(record) {
  const explicit = String(record?.order_profile || '').trim().toLowerCase()
  if (explicit) return explicit

  const tagged = extractTaggedValue(record?.notes, 'ORDER_PROFILE')
  if (tagged) return tagged

  return 'business'
}

function isDistributorSubmission(record) {
  return getApplicationTypeFromRecord(record) === 'distributor'
}

const defaultClientProfile = {
  customerType: 'company',
  customerName: '',
  contactPersonName: '',
  vatNumber: '',
  shippingType: 'road',
  contactPhone: '',
  contactEmail: '',
  invoiceAddressLine1: '',
  invoiceAddressLine2: '',
  invoiceArea: '',
  invoiceRegion: '',
  invoiceCountry: '',
  invoicePostalCode: '',
  shippingSameAsInvoice: true,
  shippingName: '',
  shippingPhone: '',
  shippingAddressLine1: '',
  shippingAddressLine2: '',
  shippingArea: '',
  shippingRegion: '',
  shippingCountry: '',
  shippingPostalCode: '',
}

function buildClientProfileFromRegistration(registration) {
  if (!registration || typeof registration !== 'object') {
    return { ...defaultClientProfile }
  }

  const shippingSameAsInvoice = registration.shipping_same_as_invoice !== false

  return {
    ...defaultClientProfile,
    customerType: registration.customer_type || 'company',
    customerName: registration.company_name || '',
    contactPersonName: registration.contact_name || registration.company_name || '',
    vatNumber: registration.vat_number || registration.vies_vat || '',
    shippingType: registration.shipping_type || 'road',
    contactPhone: registration.phone || registration.contact_phone || '',
    contactEmail: registration.contact_email || registration.customer_email || '',
    invoiceAddressLine1: registration.invoice_address_line1 || registration.address || '',
    invoiceAddressLine2: registration.invoice_address_line2 || '',
    invoiceArea: registration.invoice_area || registration.city || '',
    invoiceRegion: registration.invoice_region || registration.region || '',
    invoiceCountry: registration.invoice_country || registration.country || '',
    invoicePostalCode: registration.invoice_postal_code || registration.postal_code || '',
    shippingSameAsInvoice,
    shippingName: registration.shipping_name || '',
    shippingPhone: registration.shipping_phone || '',
    shippingAddressLine1: registration.shipping_address_line1 || registration.invoice_address_line1 || registration.address || '',
    shippingAddressLine2: registration.shipping_address_line2 || '',
    shippingArea: registration.shipping_area || '',
    shippingRegion: registration.shipping_region || registration.invoice_region || registration.region || '',
    shippingCountry: registration.shipping_country || registration.invoice_country || registration.country || '',
    shippingPostalCode: registration.shipping_postal_code || registration.invoice_postal_code || registration.postal_code || '',
  }
}

function buildClientProfileFromOrderEditHandoff(handoff) {
  if (!handoff || typeof handoff !== 'object') {
    return { ...defaultClientProfile }
  }

  const consigneeName = String(handoff.consigneeName || '').trim()
  const consigneePhone = String(handoff.consigneePhone || '').trim()
  const shippingAddress = String(handoff.shippingAddress || '').trim()
  const customerEmail = String(handoff.customerEmail || '').trim()

  return {
    ...defaultClientProfile,
    contactPersonName: consigneeName,
    contactPhone: consigneePhone,
    contactEmail: customerEmail,
    invoiceAddressLine1: shippingAddress,
    shippingSameAsInvoice: true,
    shippingName: consigneeName,
    shippingPhone: consigneePhone,
    shippingAddressLine1: shippingAddress,
  }
}

function buildUserMetadataFromRegistration(registration) {
  const profile = buildClientProfileFromRegistration(registration)

  return {
    customer_type: profile.customerType,
    account_type: profile.customerType,
    company_name: profile.customerName,
    full_name: registration?.contact_name || profile.customerName,
    vat_number: profile.vatNumber,
    contact_phone: profile.contactPhone,
    contact_email: profile.contactEmail,
    shipping_type: profile.shippingType,
    invoice_address_line1: profile.invoiceAddressLine1,
    invoice_address_line2: profile.invoiceAddressLine2,
    invoice_area: profile.invoiceArea,
    invoice_region: profile.invoiceRegion,
    invoice_country: profile.invoiceCountry,
    invoice_postal_code: profile.invoicePostalCode,
    shipping_same_as_invoice: profile.shippingSameAsInvoice,
    shipping_name: profile.shippingName,
    shipping_phone: profile.shippingPhone,
    shipping_address_line1: profile.shippingAddressLine1,
    shipping_address_line2: profile.shippingAddressLine2,
    shipping_area: profile.shippingArea,
    shipping_region: profile.shippingRegion,
    shipping_country: profile.shippingCountry,
    shipping_postal_code: profile.shippingPostalCode,
    distributor_tier: registration?.distributor_tier || null,
    prices_allocated: Boolean(registration?.prices_allocated),
    registration_status: 'approved',
    registration_id: registration?.id || null,
  }
}

function composeAddress({ line1, line2, area, region, country, postalCode }) {
  return [line1, line2, area, region, postalCode, country]
    .map((value) => String(value || '').trim())
    .filter(Boolean)
    .join(', ')
}

function hasReachedComplianceDate(referenceDate = new Date()) {
  const complianceStart = new Date(`${COMPLIANCE_DATE}T00:00:00.000Z`)
  const comparedDate = referenceDate instanceof Date ? referenceDate : new Date(referenceDate)
  return Number.isFinite(comparedDate.getTime()) && comparedDate.getTime() >= complianceStart.getTime()
}

function getSilverFreeGuaranteeText(referenceDate = new Date()) {
  return hasReachedComplianceDate(referenceDate) ? `${SILVER_FREE_GUARANTEE_BADGE} — CI 77820-FREE` : ''
}

/**
 * Updates document.title, the meta[name="description"], and link[rel="canonical"]
 * for the current route. Used in page-level useEffect calls.
 * Returns a cleanup function that restores the default home-page SEO values.
 */
function setPageSEO({ title, description, canonical } = {}) {
  const SITE_NAME = 'GEL.IT.UP by GIUP®'
  const DEFAULT_TITLE = `${SITE_NAME} | Gel Polish, Builder Gel & Nail Systems`
  const DEFAULT_DESCRIPTION = 'Professional gel polish with 1,000+ shades, builder gel systems, base coats and top coats. HEMA-free, TPO-free, EU certified. Available wholesale to professional nail technicians worldwide.'
  const DEFAULT_CANONICAL = 'https://gelitup.com/'

  const resolvedTitle = title
    ? (title.includes('GEL.IT.UP') ? title : `${title} | ${SITE_NAME}`)
    : DEFAULT_TITLE

  document.title = resolvedTitle

  const metaDesc = document.querySelector('meta[name="description"]')
  if (metaDesc) metaDesc.setAttribute('content', description || DEFAULT_DESCRIPTION)

  const canonicalLink = document.querySelector('link[rel="canonical"]')
  if (canonicalLink) canonicalLink.setAttribute('href', canonical || DEFAULT_CANONICAL)

  // Keep Open Graph in sync for social sharing of inner pages
  const ogTitle = document.querySelector('meta[property="og:title"]')
  if (ogTitle) ogTitle.setAttribute('content', resolvedTitle)
  const ogDesc = document.querySelector('meta[property="og:description"]')
  if (ogDesc) ogDesc.setAttribute('content', description || DEFAULT_DESCRIPTION)
  const ogUrl = document.querySelector('meta[property="og:url"]')
  if (ogUrl) ogUrl.setAttribute('content', canonical || DEFAULT_CANONICAL)
  const twTitle = document.querySelector('meta[name="twitter:title"]')
  if (twTitle) twTitle.setAttribute('content', resolvedTitle)
  const twDesc = document.querySelector('meta[name="twitter:description"]')
  if (twDesc) twDesc.setAttribute('content', description || DEFAULT_DESCRIPTION)

  return () => {
    document.title = DEFAULT_TITLE
    if (metaDesc) metaDesc.setAttribute('content', DEFAULT_DESCRIPTION)
    if (canonicalLink) canonicalLink.setAttribute('href', DEFAULT_CANONICAL)
    if (ogTitle) ogTitle.setAttribute('content', DEFAULT_TITLE)
    if (ogDesc) ogDesc.setAttribute('content', DEFAULT_DESCRIPTION)
    if (ogUrl) ogUrl.setAttribute('content', DEFAULT_CANONICAL)
    if (twTitle) twTitle.setAttribute('content', DEFAULT_TITLE)
    if (twDesc) twDesc.setAttribute('content', DEFAULT_DESCRIPTION)
  }
}

function normalizeSkuCode(value) {
  return String(value || '').trim().toUpperCase().replace(/\s+/g, ' ')
}

function normalizeProductName(value) {
  return normalizeSkuCode(value)
    .replace(/GEL\.?IT\.?UP|GEL\s*IT\s*UP|GIUP/gi, ' ')
    .replace(/(\d)(ML|GR|G)\b/gi, '$1 $2')
    .replace(/\b(HTF|HTE|HEMA\s*FREE|HEMAFREE)\b/gi, ' ')
    .replace(/\bGR\b/gi, 'G')
    .replace(/[^A-Z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function deriveSpreadsheetSynonymKeys(name) {
  const normalized = normalizeProductName(name)
  if (!normalized) return []

  const keys = new Set()
  const add = (...values) => {
    values.forEach((value) => {
      const key = normalizeSkuCode(value)
      if (key) keys.add(key)
    })
  }

  const classicBuilderMatch = normalized.match(/^3 IN 1 BUILDER GEL\s+(.+?)\s+40 G$/)
  if (classicBuilderMatch) {
    const shade = classicBuilderMatch[1]
    add(`3 IN 1 ${shade}`, `3IN1${shade.replace(/\s+/g, '')}`, `3 IN 1 BUILDER GEL ${shade}`)
  }

  const shimmeryBuilderMatch = normalized.match(/^3 IN 1 SHIMMERY BUILDER GEL\s+40 G\s+(.+)$/)
  if (shimmeryBuilderMatch) {
    const shade = shimmeryBuilderMatch[1]
    const legacyShadeMap = {
      'CLEAR IRIDESCENT': 'IRIDESCENT SHIMMER CLEAR',
      'COVER': 'SHIMMER COVER',
      'LIGHT LILAC': 'SHIMMER LILAC',
      'PINK MARMALADE': 'MARMELADE SHIMMER PINK',
    }
    const legacyShade = legacyShadeMap[shade]
    if (legacyShade) {
      add(`3 IN 1 BUILDER GEL ${legacyShade}`, `3 IN 1 BUILDER GEL ${legacyShade} B`)
    }
  }

  const premiumBuilderMatch = normalized.match(/^PREMIUM BUILDER GEL\s+(.+?)\s+40 GR$/)
  if (premiumBuilderMatch) {
    const shade = premiumBuilderMatch[1]
    add(`3 IN 1 GELITUP PREMIUM BUILDER GEL ${shade}`, `3 IN 1 GELITUP PREMIUM BUILDER GEL ${shade} B`)
    if (shade === 'PEARLY NUDE') {
      add('3 IN 1 PREMIUM BUILDER GEL SHIMMER NUDE', '3 IN 1 PREMIUM BUILDER GEL SHIMMER NUDE B')
    }
    if (shade === 'PEARLY PINK') {
      add('3 IN 1 PREMIUM BUILDER GEL SHIMMER PINK', '3 IN 1 PREMIUM BUILDER GEL SHIMMER PINK B')
    }
  }

  if (normalized === 'PREMIUM PLUS FIBER GLASS BUILDER GEL 40 GR') {
    add(
      '3 IN 1 GELITUP PREMIUM BUILDER GEL CLEAR PLUS',
      '3 IN 1 GELITUP PREMIUM BUILDER GEL CLEAR PLUS B',
      '3 IN 1 PREMIUM PLUS',
      '3 IN 1.PREMIUM.PLUS',
    )
  }

  const brushOnBuilderMatch = normalized.match(/^BRUSH ON BUILDER GEL\s+(.+?)\s+15 ML$/)
  if (brushOnBuilderMatch) {
    const shade = brushOnBuilderMatch[1]
    add(`BRUSH ON BUILDER BIAB ${shade}`)
    if (shade === 'BLUSH PINK') {
      add('BRUSH ON BUILDER BIAB IRRIDESCENT PINK', 'BRUSH ON BUILDER BIAB IRRODESCENT PINK')
    }
    if (shade === 'GLITTERY PINK') {
      add('BRUSH ON BUILDER BIAB GLITTER PINK')
    }
  }

  if (normalized === 'SUPERBOND NAIL DEHYDRATOR 11 ML ACID FREE') {
    add('SUPERBOND WITHOUT ACID', 'SUPERBOND.WITHOUT.ACID')
  }

  if (normalized === 'SUPERBOND NAIL DEHYDRATOR 11 ML WITH ACID') {
    add('SUPERBOND WITH ACID', 'SUPERBOND.WITH.ACID')
  }

  if (normalized === 'BASE COAT 15 ML') {
    add('CLASSIC BASE COAT')
  }

  if (normalized === 'ACRYLIC COMPETE POWDER COVER 35 G') {
    add('ACRYLICS COVER')
  }

  if (normalized === 'ACRYLIC COMPETE POWDER EXTREME WHITE 35 G') {
    add('ACRYLICS EXTREME WHITE')
  }

  if (normalized === 'ACRYLIC COMPETE POWDER PINK 35 G') {
    add('ACRYLICS PINK')
  }

  if (normalized === 'ACRYLIC CLASSIC POWDER WHITE 35 G' || normalized === 'ACRYLIC COMPETE POWDER MILKY WHITE 35 G') {
    add('ACRYLICS WHITE')
  }

  if (/^2113\b/.test(normalized)) {
    add('SFT 2113')
  }

  const autumn2021Match = normalized.match(/^AUTUMN 2021 OTA(\d{2})$/)
  if (autumn2021Match) {
    add(`GIUP ODA${autumn2021Match[1]}`)
  }

  const btbMatch = normalized.match(/^BTB(\d{2})\b/)
  if (btbMatch) {
    add(`GIUP B2B${btbMatch[1]}`)
  }

  const multimixMatch = normalized.match(/^MULTIMIX SYNTHOGEL (30|60) G (.+)$/)
  if (multimixMatch) {
    const size = multimixMatch[1]
    const shade = multimixMatch[2]
    const multimixAliasMap = {
      '30:BABY BLUE': ['MULTIMIX BABY BLUE COLOR'],
      '30:BABY PINK GLITTER': ['MULTIMIX BABY PINK GLITTER COLOR'],
      '30:BLUE GLITTER': ['MULTIMIX BLUE GLITTER COLOR'],
      '30:BUBBLE GUM GLITTER': ['MULTIMIX BUBBLE GUM GLITTER COLOR', 'MULTIMIX BUBBLEGUM GLITTER COLOR'],
      '30:CLEAR': ['MULTIMIX CLEAR COLOR'],
      '30:GLITSY GREEN': ['MULTIMIX GLITSY GREEN COLOR'],
      '30:LIGHT NUDE': ['MULTIMIX LIGHT NUDE COLOR'],
      '30:MINTY GREEN': ['MULTIMIX MINT GREEN COLOR'],
      '30:PINK III': ['MULTIMIX PINKIII COLOR'],
      '30:SUPER SOFT PINK': ['MULTIMIX SUPER SOFT PINK COLOR'],
      '60:BLACK': ['MULTIMIX BLACK COLOR'],
      '60:CLEAR': ['MULTIMIX CLEAR COLOR'],
      '60:CLEAR GLITTER': ['MULTIMIX GLITTERS CLEAR'],
      '60:COVER': ['MULTIMIX COVER COLOR'],
      '60:COVER II': ['MULTIMIX COVER II COLOR'],
      '60:CRYSTAL CLEAR': ['MULTIMIX CRYSTAL CLEAR COLOR'],
      '60:GLITTER GOLD': ['MULTIMIX GLITTERS GOLD'],
      '60:GLITTER NUDE': ['MULTIMIX GLITTERS NUDE'],
      '60:GLITTER PINK': ['MULTIMIX GLITTERS PINK', 'MULTIMIX GLITTERPINK COLOR'],
      '60:GLITTER PINK II': ['MULTIMIX PINK II COLOR'],
      '60:GLITTER WHITE': ['MULTIMIX GLITTERS WHITE'],
      '60:LIGHT LILAC': ['MULTIMIX LILAC COLOR'],
      '60:LIGHT PINK': ['MULTIMIX LIGHT PINK COLOR'],
      '60:MILKY WHITE': ['MULTIMIX MILKY WHITE COLOR'],
      '60:NUDE': ['MULTIMIX NUDE COLOR'],
      '60:PINK': ['MULTIMIX PINK COLOR'],
      '60:PINK II': ['MULTIMIX PINK II COLOR'],
      '60:SUPER MILKY': ['MULTIMIX SUPER MILKY COLOR'],
      '60:WHITE': ['MULTIMIX WHITE COLOR', 'MULTIMIX WHITE 60ML 60G'],
    }
    const aliases = multimixAliasMap[`${size}:${shade}`] || []
    aliases.forEach((alias) => {
      add(alias, `${alias} ${size}G`, `${alias} ${size} G`, `${alias} B ${size}G`, `${alias} B ${size} G`, `${alias} C ${size}G`, `${alias} C ${size} G`)
    })
  }

  return [...keys]
}

function applyProductAliasGroupsToPriceMap(map, normalizeTarget, aliasGroups = PRODUCT_ALIAS_GROUPS) {
  const lookupEntry = (target) => map.get(normalizeTarget(target))

  for (const { codes, target } of aliasGroups) {
    const entry = lookupEntry(target)
    if (!entry) continue

    for (const code of codes) {
      const normalizedCode = normalizeSkuCode(code)
      const normalizedName = normalizeProductName(code)
      if (normalizedCode && !map.has(normalizedCode)) map.set(normalizedCode, entry)
      if (normalizedName && !map.has(normalizedName)) map.set(normalizedName, entry)
      if (!map.has(code)) map.set(code, entry)
    }
  }
}

