const EUR_CURRENCY_CODE = 'EUR'
const FACTORY_PRICE_BOOK_EUR = {
  professionalPackDiscountPct: 15,
}

function currencyFormatter(amount, currencyCode = EUR_CURRENCY_CODE) {
  return new Intl.NumberFormat('en-IE', {
    style: 'currency',
    currency: currencyCode,
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(Number(amount || 0))
}

function formatOptionalCurrency(amount, currencyCode = EUR_CURRENCY_CODE) {
  if (amount == null || Number.isNaN(Number(amount))) return '-'
  return currencyFormatter(amount, currencyCode)
}

function proformaLookupPrice(priceMap, code, productName) {
  if (!priceMap || !priceMap.size) return null
  const normalized = normalizeSkuCode(code)
  // Direct code lookup
  const byCode = priceMap.get(normalized)
  if (byCode?.price != null) return byCode.price
  // By product name
  if (productName) {
    const byName = priceMap.get(normalizeProductName(productName))
    if (byName?.price != null) return byName.price
  }
  // Strip GIUP prefix: "GIUP N008" → "N008", "GIUP 204" → "204"
  const stripped = normalized.replace(/^GIUP[-\s]+/, '')
  if (stripped !== normalized) {
    const byStripped = priceMap.get(stripped)
    if (byStripped?.price != null) return byStripped.price
    // Try zero-padded and zero-stripped variants for number codes
    const numOnly = stripped.match(/^(\d+[A-Z]?)$/)
    if (numOnly) {
      const padded = numOnly[1].replace(/^(\d+)/, n => n.padStart(2, '0'))
      const unpadded = numOnly[1].replace(/^0+(\d)/, '$1')
      const e = priceMap.get(padded) || priceMap.get(unpadded)
      if (e?.price != null) return e.price
    }
    // Try series+number: "GIUP BTO02" → "BTO 02", "BTO02"
    const seriesMatch = stripped.match(/^([A-Z]+)(\d+[A-Z]?)$/)
    if (seriesMatch) {
      const s = seriesMatch[1], n = seriesMatch[2]
      const e = priceMap.get(`${s} ${n}`) || priceMap.get(`${s} ${n.padStart(2, '0')}`) || priceMap.get(`${s}${n}`) || priceMap.get(`${s}${n.padStart(2, '0')}`)
      if (e?.price != null) return e.price
    }
  }
  return null
}

// Word-overlap fuzzy fallback — used when direct code/name lookups in a priceMap fail
function fuzzyPriceLookup(itemCode = '', itemName = '', wordIndex = []) {
  if (!Array.isArray(wordIndex) || wordIndex.length === 0) return null
  const queryWords = new Set([
    ...normalizeSkuCode(itemCode).split(/\s+/),
    ...normalizeSkuCode(itemName).split(/\s+/),
  ].filter(w => w.length >= 3))
  if (queryWords.size === 0) return null
  let bestEntry = null
  let bestScore = 0
  for (const { words, entry } of wordIndex) {
    let overlap = 0
    for (const w of queryWords) {
      if (words.has(w)) overlap++
    }
    if (overlap >= 2 && overlap > bestScore) {
      bestScore = overlap
      bestEntry = entry
    }
  }
  return bestEntry
}

function buildProformaFromCart({
  orderId,
  userProfile,
  selectedCodes,
  itemQtys,
  packageCartItems,
  includeProfessionalBasePack,
  products,
  priceMap,
  tierPriceMultiplier = 1.0,
  authorityOverrides = null,
  tier = null,
}) {
  const productMap = new Map(products.map((product) => [normalizeSkuCode(product.code), product]))
  // Returns the effective multiplier for a given product name/code, respecting authority overrides.
  const resolveItemMultiplier = (name, code) => {
    if (tier !== 'authority' || !authorityOverrides?.rules?.length) return tierPriceMultiplier
    const n = String(name || '').toLowerCase()
    const s = String(code || '').toLowerCase()
    for (const rule of authorityOverrides.rules) {
      if (rule.patterns?.some(p => n.includes(String(p).toLowerCase()) || s.includes(String(p).toLowerCase()))) {
        return rule.multiplier
      }
    }
    return tierPriceMultiplier
  }

  const selectedLines = selectedCodes.map((code) => {
    const normalized = normalizeSkuCode(code)
    const product = productMap.get(normalized)
    const basePriceEur = product?.price ?? proformaLookupPrice(priceMap, code, product?.name) ?? null
    const mult = resolveItemMultiplier(product?.name, code)
    const unitPriceEur = basePriceEur != null
      ? Number((basePriceEur * mult).toFixed(2))
      : null
    const qty = Number(itemQtys?.[code] || itemQtys?.[normalized] || 1)

    return {
      sku: normalized,
      description: product?.name || 'Catalog item',
      qty,
      unitPriceEur,
      discountPct: 0,
      subtotalEur: unitPriceEur != null ? Number((qty * unitPriceEur).toFixed(2)) : null,
    }
  })

  const packageLines = packageCartItems.map((item) => {
    const product = productMap.get(normalizeSkuCode(item.sku))
    const basePriceEur = product?.price ?? item.price ?? proformaLookupPrice(priceMap, item.sku, item.name) ?? null
    const mult = resolveItemMultiplier(item.name || product?.name, item.sku)
    const unitPriceEur = basePriceEur != null
      ? Number((basePriceEur * mult).toFixed(2))
      : null
    const qty = Number(item.qty || 0)
    return {
      sku: item.sku,
      description: item.name || item.code || item.sku,
      qty,
      unitPriceEur,
      discountPct: 0,
      subtotalEur: unitPriceEur != null ? Number((qty * unitPriceEur).toFixed(2)) : null,
    }
  })

  const addOnLines = includeProfessionalBasePack
    ? (() => {
      const addOnProduct = productMap.get(normalizeSkuCode(PROFESSIONAL_BASE_PACK.sku))
      const listUnitPriceEur = addOnProduct?.price ?? proformaLookupPrice(priceMap, PROFESSIONAL_BASE_PACK.sku, addOnProduct?.name || PROFESSIONAL_BASE_PACK.description) ?? null
      const discountPct = FACTORY_PRICE_BOOK_EUR.professionalPackDiscountPct
      const discountedUnitPriceEur = listUnitPriceEur != null
        ? Number((listUnitPriceEur * (1 - (discountPct / 100)) * tierPriceMultiplier).toFixed(2))
        : null
      const qty = PROFESSIONAL_BASE_PACK.qty
      return [{
        sku: PROFESSIONAL_BASE_PACK.sku,
        description: PROFESSIONAL_BASE_PACK.description,
        qty,
        unitPriceEur: discountedUnitPriceEur,
        discountPct,
        subtotalEur: discountedUnitPriceEur != null ? Number((qty * discountedUnitPriceEur).toFixed(2)) : null,
      }]
    })()
    : []

  const lines = [...selectedLines, ...packageLines, ...addOnLines]
  const subtotalEur = Number(lines.reduce((sum, line) => sum + (line.subtotalEur || 0), 0).toFixed(2))
  const country = userProfile?.country || '-'
  const vatTreatment = resolveVatTreatment(country)
  const vatInfo = getVatTreatmentLabel(vatTreatment, country)
  const vatAmountEur = Number((subtotalEur * vatInfo.pct / 100).toFixed(2))
  const grandTotalEur = Number((subtotalEur + vatAmountEur).toFixed(2))

  return {
    orderId,
    createdAtIso: new Date().toISOString(),
    customer: {
      companyName: userProfile?.companyName || '-',
      vatNumber: userProfile?.vatNumber || '-',
      country,
      region: userProfile?.region || '-',
    },
    lines,
    subtotalEur,
    vatTreatment,
    vatPct: vatInfo.pct,
    vatLabel: vatInfo.label,
    vatNote: vatInfo.note,
    vatAmountEur,
    grandTotalEur,
    currency: EUR_CURRENCY_CODE,
  }
}

function buildTierPackageItems(tier, podCatalog, defaultQty = DEFAULT_PACKAGE_ITEM_QTY) {
  const pod1 = Array.isArray(podCatalog?.pod_1) ? podCatalog.pod_1 : []
  const pod2 = Array.isArray(podCatalog?.pod_2) ? podCatalog.pod_2 : []
  const pod3 = Array.isArray(podCatalog?.pod_3) ? podCatalog.pod_3 : []
  const pod4 = Array.isArray(podCatalog?.pod_4) ? podCatalog.pod_4 : []

  const source = tier === 'Silver'
    ? pod1
    : tier === 'Gold'
      ? [...pod1, ...pod2]
      : [...pod1, ...pod2, ...pod3, ...pod4]

  return source.map((item) => ({
    sku: item.sku,
    code: item.code,
    name: item.name,
    category: item.category,
    group: item.group,
    qty: defaultQty,
  }))
}

function buildTierTechnicalItems(defaultQty = DEFAULT_PACKAGE_ITEM_QTY) {
  return PACKAGE_TECH_ESSENTIALS.map((item) => ({
    ...item,
    qty: defaultQty,
  }))
}

function buildPackageDraftInvoice(
  tier,
  buyerEmail = 'b2b-client@company.com',
  packageItems = [],
  additionalLineItems = [],
) {
  const createdAt = new Date().toISOString()
  const invoiceNumber = `DRAFT-${tier.toUpperCase()}-${Date.now()}`

  const lineItems = [
    ...packageItems.map((item) => ({
      sku: item.sku,
      description: `${item.name} (${item.code})`,
      qty: item.qty,
    })),
    ...additionalLineItems,
  ]
  const colorCodes = packageItems
    .filter((item) => item.code)
    .map((item) => item.code)
  const totalUnits = lineItems.reduce((sum, item) => sum + item.qty, 0)

  return {
    invoiceNumber,
    tier,
    createdAt,
    buyerEmail,
    colorCodes,
    lineItems,
    totalUnits,
  }
}

