function formatCatalogueItemName(rawPath = '') {
  const fileName = rawPath.split('/').pop() || ''
  const withoutExtension = fileName.replace(/\.[a-z0-9]+$/i, '')
  return withoutExtension
    .replace(/[_-]+/g, ' ')
    .replace(/\bMIRROR TOP COAT\b/gi, 'Mirror Powder Top Coat')
    .replace(/\bIRRODESCENT\b/gi, 'IRRIDESCENT')
    .replace(/\s+/g, ' ')
    .trim()
}

function formatCatalogueDisplayKey(rawKey = '') {
  return String(rawKey || '')
    .replace(/\.[a-z0-9]+$/i, '')
    .replace(/[_.-]+/g, ' ')
    .replace(/\bMIRROR TOP COAT\b/gi, 'Mirror Powder Top Coat')
    .replace(/\bIRRODESCENT\b/gi, 'IRRIDESCENT')
    .replace(/\s+/g, ' ')
    .trim()
}

function formatPortalDateTime(value) {
  if (!value) return 'Date unavailable'

  const parsedDate = new Date(value)
  return Number.isNaN(parsedDate.getTime()) ? String(value) : parsedDate.toLocaleString()
}

function normalizePortalOrderItems(rawItems) {
  if (Array.isArray(rawItems)) {
    return rawItems
      .map((item) => {
        if (typeof item === 'string') return item.trim()
        if (item && typeof item === 'object') {
          return [item.name, item.sku, item.code]
            .map((value) => String(value || '').trim())
            .find(Boolean) || ''
        }
        return ''
      })
      .filter(Boolean)
  }

  if (typeof rawItems === 'string') {
    try {
      return normalizePortalOrderItems(JSON.parse(rawItems))
    }
    catch {
      return rawItems
        .split(',')
        .map((item) => String(item || '').trim())
        .filter(Boolean)
    }
  }

  return []
}

function normalizePortalOrderRow(order) {
  if (!order || typeof order !== 'object') return null

  const normalizedItems = normalizePortalOrderItems(order.items)
  const numericUnits = Number(order.total_units)

  return {
    ...order,
    items: normalizedItems,
    total_units: Number.isFinite(numericUnits) ? numericUnits : normalizedItems.length,
  }
}

class PortalModuleErrorBoundary extends Component {
  constructor(props) {
    super(props)
    this.state = { hasError: false, errorMessage: '' }
  }

  static getDerivedStateFromError(error) {
    return {
      hasError: true,
      errorMessage: error instanceof Error ? error.message : 'Unexpected portal error',
    }
  }

  componentDidCatch(error, errorInfo) {
    console.error('[PortalModuleErrorBoundary]', error, errorInfo)
  }

  componentDidUpdate(prevProps) {
    if (prevProps.resetKey !== this.props.resetKey && this.state.hasError) {
      this.setState({ hasError: false, errorMessage: '' })
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <section className="rounded-2xl border border-rose-200 bg-rose-50 p-5 text-sm text-rose-700">
          <p className="font-semibold">{this.props.moduleLabel || 'Portal section'} could not be loaded.</p>
          <p className="mt-1">The page did not render correctly, but the portal session is still active.</p>
          {this.state.errorMessage && (
            <p className="mt-2 text-xs text-rose-600">Error: {this.state.errorMessage}</p>
          )}
        </section>
      )
    }

    return this.props.children
  }
}

function scoreCatalogueDisplayKey(rawKey = '', formattedKey = '') {
  const normalized = normalizeCatalogueToken(formattedKey)
  if (!normalized) return Number.NEGATIVE_INFINITY
  if (isLikelySwatchName(formattedKey)) return Number.NEGATIVE_INFINITY
  if (/^(2026 NEW|NAIL PREP)\b/.test(normalized)) return Number.NEGATIVE_INFINITY

  let score = 0
  if (/\bHTF\b/i.test(rawKey)) score += 10
  if (/\b\d+\s*ML\b/i.test(formattedKey)) score += 4
  if (/\s/.test(formattedKey)) score += 2
  if (!/[_.]/.test(rawKey)) score += 2
  if (!/^GIUP(?:\s|[-])/i.test(rawKey)) score += 2
  if (!/^2026-NEW/i.test(rawKey)) score += 2
  if (formattedKey.length >= 12) score += 1

  return score
}

function extractCatalogueProductCode(rawKey = '') {
  const normalized = normalizeSkuCode(rawKey)
  if (!normalized) return ''

  const explicitSeriesCodeMatch = normalized.match(/\b(SCE\d{1,3}[A-Z]?|VCE\d{1,3}[A-Z]?|GCE\d{1,3}[A-Z]?|DCE\d{1,3}[A-Z]?|RQCE\d{1,3}[A-Z]?|TFG\d{1,3}[A-Z]?|BTO\d{1,3}[A-Z]?|BTB\d{1,3}[A-Z]?|OTA\d{1,3}[A-Z]?|JNF\d{1,3}[A-Z]?|NYP\d{1,3}[A-Z]?|AD\d{1,3}[A-Z]?|MC\d{1,3}[A-Z]?|SH\d{1,3}[A-Z]?)\b/i)
  if (explicitSeriesCodeMatch) return explicitSeriesCodeMatch[1].toUpperCase()

  const giupNumericMatch = normalized.match(/\bGIUP\s+(\d{3,4}[A-Z]?)\b/i)
  if (giupNumericMatch) return giupNumericMatch[1]

  const brushOnBuilderNameMatch = normalized.match(/\bBRUSH\s+ON\s+BUILDER(?:\s+GEL|\s+BIAB)?\s+(.+)$/i)
  if (brushOnBuilderNameMatch) {
    const shade = brushOnBuilderNameMatch[1]
      .replace(/\b15\s*ML\b/gi, '')
      .replace(/\bHTF\b/gi, '')
      .replace(/\b1\b$/g, '')
      .replace(/\s+/g, ' ')
      .trim()
    if (shade) return `BOB ${shade}`
  }

  const bobCodeMatch = normalized.match(/\bBOB\s+(.+)$/i)
  if (bobCodeMatch) {
    const shade = bobCodeMatch[1]
      .replace(/\b1\b$/g, '')
      .replace(/\s+/g, ' ')
      .trim()
    if (shade) return `BOB ${shade}`
  }

  const leadingNumericMatch = normalized.match(/^(\d{3,4}[A-Z]?)\b/)
  if (leadingNumericMatch && leadingNumericMatch[1] !== '2026') return leadingNumericMatch[1]

  const prefixedNumericMatch = normalized.match(/\b[A-Z]{2,5}\s+(\d{3,4}[A-Z]?)\b/)
  if (prefixedNumericMatch) return prefixedNumericMatch[1]

  return ''
}

function buildCanonicalDisplayNameByProductCode(payload) {
  const displayNameByCode = new Map()
  const scoreByCode = new Map()

  Object.entries(payload || {}).forEach(([rawKey, rawValue]) => {
    const imageUrl = typeof rawValue === 'string' ? rawValue.trim() : ''
    if (!imageUrl || !imageUrl.includes('/gelitup-content/product-images/')) return

    const productCode = extractCatalogueProductCode(rawKey)
    if (!productCode) return

    const formattedKey = formatCatalogueDisplayKey(rawKey)
    const score = scoreCatalogueDisplayKey(rawKey, formattedKey)
    if (!Number.isFinite(score) || score < 7) return

    const currentScore = scoreByCode.get(productCode) ?? Number.NEGATIVE_INFINITY
    if (score <= currentScore) return

    scoreByCode.set(productCode, score)
    displayNameByCode.set(productCode, formattedKey)
  })

  return displayNameByCode
}

function buildCanonicalDisplayNameByImagePath(payload, canonicalDisplayNameByProductCode) {
  const displayNameByImagePath = new Map()

  Object.entries(payload || {}).forEach(([rawKey, rawValue]) => {
    const imageUrl = typeof rawValue === 'string' ? rawValue.trim() : ''
    if (!imageUrl || !imageUrl.includes('/gelitup-content/product-images/')) return

    const productCode = extractCatalogueProductCode(rawKey)
    if (!productCode) return

    const canonicalDisplayName = canonicalDisplayNameByProductCode.get(productCode)
    if (!canonicalDisplayName) return

    displayNameByImagePath.set(imageUrl, canonicalDisplayName)
  })

  return displayNameByImagePath
}

function buildPreferredDisplayNameByImagePath(payload) {
  const displayNameByImagePath = new Map()
  const scoreByImagePath = new Map()

  Object.entries(payload || {}).forEach(([rawKey, rawValue]) => {
    const imageUrl = typeof rawValue === 'string' ? rawValue.trim() : ''
    if (!imageUrl || !imageUrl.includes('/gelitup-content/product-images/')) return

    const formattedKey = formatCatalogueDisplayKey(rawKey)
    const score = scoreCatalogueDisplayKey(rawKey, formattedKey)
    if (!Number.isFinite(score) || score < 7) return

    const currentScore = scoreByImagePath.get(imageUrl) ?? Number.NEGATIVE_INFINITY
    if (score <= currentScore) return

    scoreByImagePath.set(imageUrl, score)
    displayNameByImagePath.set(imageUrl, formattedKey)
  })

  return displayNameByImagePath
}

function scoreCatalogueSourceKey(rawKey = '') {
  const normalized = normalizeSkuCode(rawKey)
  if (!normalized) return Number.NEGATIVE_INFINITY

  let score = 0
  if (/^2026-NEW-/i.test(rawKey)) score += 12
  if (/^GIUP[-\t _]/i.test(rawKey)) score += 10
  if (/\b(?:SCE|VCE|GCE|DCE|RQCE|TFG|BTO|BTB|BOB|CMU|CDC|CDCL|FR|OTA|JNF|NYP|AD|MC|SH)\d+[A-Z0-9-]*\b/i.test(normalized)) score += 10
  if (/\bBOB\b/i.test(normalized)) score += 8
  if (/\bSCE\d+\b/i.test(normalized)) score += 8
  if (!/\s/.test(rawKey)) score += 2
  if (/[_.-]/.test(rawKey)) score += 1
  return score
}

function buildPreferredSourceKeyByImagePath(payload) {
  const sourceKeyByImagePath = new Map()
  const scoreByImagePath = new Map()

  Object.entries(payload || {}).forEach(([rawKey, rawValue]) => {
    const imageUrl = typeof rawValue === 'string' ? rawValue.trim() : ''
    if (!imageUrl || !imageUrl.includes('/gelitup-content/product-images/')) return

    const score = scoreCatalogueSourceKey(rawKey)
    if (!Number.isFinite(score)) return

    const currentScore = scoreByImagePath.get(imageUrl) ?? Number.NEGATIVE_INFINITY
    if (score <= currentScore) return

    scoreByImagePath.set(imageUrl, score)
    sourceKeyByImagePath.set(imageUrl, rawKey)
  })

  return sourceKeyByImagePath
}

function isCategoryHeroAssetPath(rawPath = '') {
  const fileName = String(rawPath || '').split('/').pop() || ''
  return /hero\.image/i.test(fileName)
}

function normalizeCatalogueToken(value = '') {
  return String(value || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

const CAT_EYE_COLLECTIONS = [
  { value: 'DREAMY CAT EYE', label: 'Dreamy Cat Eye', slug: 'dreamy-cat-eye' },
  { value: 'FAN', label: 'Fan Cat Eye', slug: 'fan-cat-eye' },
  { value: 'GLASS CAT EYE', label: 'Glass Cat Eye', slug: 'glass-cat-eye' },
  { value: 'NEON CAT EYE', label: 'Neon Cat Eye', slug: 'neon-cat-eye' },
  { value: 'ROSE QUARTZ CAT EYE', label: 'Rose Quartz Cat Eye', slug: 'rose-quartz-cat-eye' },
  { value: 'SAPPHIRE CAT EYE', label: 'Sapphire Cat Eye', slug: 'sapphire-cat-eye' },
  { value: 'VELVET CAT EYE', label: 'Velvet Cat Eye', slug: 'velvet-cat-eye' },
]

function getCatEyeCollectionBySlug(slug = '') {
  const normalizedSlug = String(slug || '').toLowerCase().trim()
  return CAT_EYE_COLLECTIONS.find((collection) => collection.slug === normalizedSlug) || null
}

function resolveCatEyeCollection(rawCategoryName = '', imageUrl = '') {
  const categoryToken = normalizeCatalogueToken(rawCategoryName)
  if (categoryToken === 'FAN CAT EYE') return 'FAN'
  const categoryMatch = CAT_EYE_COLLECTIONS.find((collection) => collection.value === categoryToken)
  if (categoryMatch) return categoryMatch.value

  const pathMatch = String(imageUrl || '').match(/\/COLORS\/CAT EYE\/([^/]+)\//i)
  if (!pathMatch) return null
  const pathToken = normalizeCatalogueToken(pathMatch[1])
  return CAT_EYE_COLLECTIONS.find((collection) => collection.value === pathToken)?.value || null
}

function resolveSolidGelColorFamily(rawCategoryName = '', imageUrl = '', productName = '') {
  const nestedPathMatch = String(imageUrl || '').match(/\/COLORS\/SOLID GEL POLISH\/([^/]+)\//i)
  if (nestedPathMatch) return normalizeCatalogueToken(nestedPathMatch[1])

  const flatPathMatch = String(imageUrl || '').match(/\/COLORS\/(FRENCH|NUDE|PASTEL|RONE)\//i)
  if (flatPathMatch) return flatPathMatch[1].toUpperCase() === 'RONE' ? 'GIUP1' : flatPathMatch[1].toUpperCase()

  const categoryToken = normalizeCatalogueToken(rawCategoryName)
  if (categoryToken === 'RONE') return 'GIUP1'
  if (COLOR_FAMILY_FILTERS.some((family) => family.key === categoryToken)) return categoryToken
  return resolveColorFamilyKey(productName)
}

function findCatalogueItemByMatch(items = [], rawMatch = '', used = new Set()) {
  const match = normalizeCatalogueToken(rawMatch)
  if (!match) return null

  return items.find((item) => {
    if (used.has(item.imageUrl)) return false
    const nameToken = normalizeCatalogueToken(item.name)
    const pathToken = normalizeCatalogueToken(item.imageUrl)
    return nameToken.includes(match) || pathToken.includes(match)
  }) || null
}

function isLikelySwatchName(name = '') {
  const upper = normalizeCatalogueToken(name)
  if (!upper) return false

  return upper.includes('SWATCH')
    || upper.startsWith('GIUP ')
    || /^GIUP\s*[A-Z0-9]+\s*\d+[A-Z0-9]*$/i.test(upper)
    || /^[A-Z]{2,8}\s*\d+[A-Z0-9]*$/i.test(upper)
}

function extractCatalogueFamilyKey(name = '') {
  const upper = normalizeCatalogueToken(name)
  if (!upper) return 'MISC'

  if (upper.includes('3 IN 1') || upper.includes('3IN1')) return '3IN1'
  if (upper.includes('5 IN 1') || upper.includes('5IN1')) return '5IN1'
  if (upper.startsWith('GIUP ')) {
    const compact = upper.replace(/\s+/g, '')
    const skuMatch = compact.match(/^(GIUP[A-Z0-9]+?)(\d+[A-Z0-9]*)?$/)
    if (skuMatch) return skuMatch[1]
  }

  const tokens = upper.split(' ').filter(Boolean)
  const strippedTokens = tokens.map((token) => token.replace(/^0+/, ''))
  const keep = strippedTokens.filter((token) => !/^\d+[A-Z0-9]*$/.test(token))

  if (keep.length >= 2) return `${keep[0]} ${keep[1]}`
  if (keep.length === 1) return keep[0]

  return upper
}

function sortCatalogueItems(items = []) {
  return [...items].sort((left, right) => {
    const leftFamily = extractCatalogueFamilyKey(left.name)
    const rightFamily = extractCatalogueFamilyKey(right.name)

    if (leftFamily !== rightFamily) {
      return leftFamily.localeCompare(rightFamily, undefined, { sensitivity: 'base', numeric: true })
    }

    const leftIsSwatch = isLikelySwatchName(left.name)
    const rightIsSwatch = isLikelySwatchName(right.name)

    if (leftIsSwatch !== rightIsSwatch) {
      return leftIsSwatch ? 1 : -1
    }

    return left.name.localeCompare(right.name, undefined, {
      numeric: true,
      sensitivity: 'base',
    })
  })
}

function buildManualRuleIndex(payload) {
  const rules = Array.isArray(payload?.rules) ? payload.rules : []
  const index = new Map()

  rules.forEach((rule) => {
    const category = String(rule?.category || '').trim()
    const subcategory = String(rule?.subcategory || '').trim()
    if (!category || !subcategory) return
    index.set(`${category}::${subcategory}`, rule)
  })

  return index
}

function getAlternateGalleryBaseImagePath(imagePath = '') {
  const normalizedPath = String(imagePath || '').trim()
  if (!normalizedPath) return ''

  const basePath = normalizedPath.replace(/_[BC](-[a-z0-9]+)?(\.[a-z0-9]+)$/i, '$1$2')
  return basePath !== normalizedPath ? basePath : ''
}

function getAlternateGalleryBaseImageCandidates(imagePath = '') {
  const normalizedPath = String(imagePath || '').trim()
  if (!normalizedPath) return []

  const basePath = getAlternateGalleryBaseImagePath(normalizedPath)
  if (!basePath) return []

  const candidates = [basePath]
  const lastSlashIndex = basePath.lastIndexOf('/')
  const directory = lastSlashIndex >= 0 ? basePath.slice(0, lastSlashIndex + 1) : ''
  const fileName = lastSlashIndex >= 0 ? basePath.slice(lastSlashIndex + 1) : basePath

  if (fileName.includes('-')) candidates.push(`${directory}${fileName.replace(/-/g, '_')}`)
  if (fileName.includes('_')) candidates.push(`${directory}${fileName.replace(/_/g, '-')}`)

  return Array.from(new Set(candidates))
}

function isAlternateGalleryImagePath(imagePath = '') {
  return /_[BC](-[a-z0-9]+)?\.[a-z0-9]+$/i.test(String(imagePath || '').trim())
}

function stripAlternateGallerySuffix(name = '') {
  return String(name || '').replace(/\s+B$/i, '').trim()
}

function mergeAlternateGalleryItems(items = []) {
  if (!Array.isArray(items) || items.length === 0) return items

  const merged = items.map((item) => ({
    ...item,
    galleryImages: Array.isArray(item.galleryImages) ? [...item.galleryImages] : [],
  }))
  const primaryIndexByName = new Map()
  const primaryIndexByImageUrl = new Map()

  merged.forEach((item, index) => {
    primaryIndexByImageUrl.set(item.imageUrl, index)
    if (isAlternateGalleryImagePath(item.imageUrl)) return
    const normalizedName = normalizeCatalogueToken(stripAlternateGallerySuffix(item.name))
    if (!normalizedName || primaryIndexByName.has(normalizedName)) return
    primaryIndexByName.set(normalizedName, index)
  })

  const result = []
  merged.forEach((item) => {
    if (!isAlternateGalleryImagePath(item.imageUrl)) {
      result.push(item)
      return
    }

    const normalizedName = normalizeCatalogueToken(stripAlternateGallerySuffix(item.name))
    const primaryIndex = normalizedName ? primaryIndexByName.get(normalizedName) : undefined
    let primaryItem = primaryIndex === undefined ? null : merged[primaryIndex]

    if (!primaryItem || primaryItem.imageUrl === item.imageUrl) {
      const fallbackIndex = getAlternateGalleryBaseImageCandidates(item.imageUrl)
        .map((candidatePath) => primaryIndexByImageUrl.get(candidatePath))
        .find((candidateIndex) => candidateIndex !== undefined)
      if (fallbackIndex !== undefined) {
        primaryItem = merged[fallbackIndex]
      }
    }

    if (!primaryItem || primaryItem.imageUrl === item.imageUrl) {
      result.push(item)
      return
    }

    const galleryImages = [...primaryItem.galleryImages]
    if (!galleryImages.includes(item.imageUrl)) galleryImages.push(item.imageUrl)
    item.galleryImages.forEach((imageUrl) => {
      if (!galleryImages.includes(imageUrl) && imageUrl !== primaryItem.imageUrl) galleryImages.push(imageUrl)
    })
    primaryItem.galleryImages = galleryImages
  })

  return result
}

function applyManualCatalogueOrder(items = [], rule = null) {
  if (!rule || !Array.isArray(items) || items.length === 0) {
    return sortCatalogueItems(items)
  }

  const used = new Set()
  const ordered = []
  const groups = Array.isArray(rule.groups) ? rule.groups : []
  const flatOrder = Array.isArray(rule.order) ? rule.order : []

  groups.forEach((group) => {
    const heroItem = findCatalogueItemByMatch(items, group?.hero || '', used)
    if (heroItem) {
      used.add(heroItem.imageUrl)

      const swatches = Array.isArray(group?.swatches) ? group.swatches : []
      if (group?.mergeAsGallery) {
        // Merge swatch images into hero as galleryImages — suppress them as separate tiles
        const galleryImages = [...(Array.isArray(heroItem.galleryImages) ? heroItem.galleryImages : [])]
        swatches.forEach((swatchName) => {
          const swatchItem = findCatalogueItemByMatch(items, swatchName, used)
          if (!swatchItem) return
          used.add(swatchItem.imageUrl)
          if (!galleryImages.includes(swatchItem.imageUrl)) galleryImages.push(swatchItem.imageUrl)
        })
        ordered.push({ ...heroItem, galleryImages })
      } else {
        ordered.push(heroItem)
        swatches.forEach((swatchName) => {
          const swatchItem = findCatalogueItemByMatch(items, swatchName, used)
          if (!swatchItem) return
          used.add(swatchItem.imageUrl)
          ordered.push(swatchItem)
        })
      }
    }
  })

  flatOrder.forEach((rawName) => {
    const item = findCatalogueItemByMatch(items, rawName, used)
    if (!item) return
    used.add(item.imageUrl)
    ordered.push(item)
  })

  const remainder = sortCatalogueItems(items.filter((item) => !used.has(item.imageUrl)))
  return [...ordered, ...remainder]
}

function applyHiddenProductsFilter(payload, hiddenKeys = []) {
  if (!Array.isArray(hiddenKeys) || hiddenKeys.length === 0) return payload
  const hiddenSet = new Set(hiddenKeys.map(k => String(k).trim().toLowerCase()).filter(Boolean))
  if (hiddenSet.size === 0) return payload
  const filtered = {}
  for (const [key, value] of Object.entries(payload)) {
    if (!hiddenSet.has(key.trim().toLowerCase())) filtered[key] = value
  }
  return filtered
}

function buildCatalogueSectionsFromImageMap(payload, manualRuleIndex = new Map()) {
  if (!payload || typeof payload !== 'object') return []

  const blockedCategoryTokens = new Set(['CRACK', 'THERMO', 'CREME DE LA CREME'])
  const preferredDisplayNameByImagePath = buildPreferredDisplayNameByImagePath(payload)
  const preferredSourceKeyByImagePath = buildPreferredSourceKeyByImagePath(payload)
  const canonicalDisplayNameByProductCode = buildCanonicalDisplayNameByProductCode(payload)
  const canonicalDisplayNameByImagePath = buildCanonicalDisplayNameByImagePath(payload, canonicalDisplayNameByProductCode)
  
  // Map certain folders to be subcategories of parent categories
  const categoryRemapping = new Map([
    // Colors subcategories
    ['BY THE OCEAN', 'COLORS'],
    // Nail Art subcategories
    ['COBWEB', 'NAIL ART'],
    ['LINE-IT-UP', 'NAIL ART'],
    ['LINE IT UP', 'NAIL ART'],
    // Builder Gel Systems subcategories
    ['BUILDER GEL', 'BUILDER GEL SYSTEMS'],
    ['MULTIMIX', 'BUILDER GEL SYSTEMS'],
    ['CREME DE LA CREME', 'BUILDER GEL SYSTEMS'],
    ['BRUSH ON BUILDER', 'BUILDER GEL SYSTEMS'],
    ['SYNTHOGEL & POLYGEL', 'BUILDER GEL SYSTEMS'],
    // Tools & Equipment — merge three top-level folders into one category.
    // TOOLS and BRUSHES use a fixed subcategory so all their sub-folders collapse
    // into one pill each. EQUIPMENT does NOT fix a subcategory — its sub-folders
    // (AIRBRUSH, DUST COLLECTOR, LAMPS & CURING) become individual subcategory pills.
    ['TOOLS',     { category: 'TOOLS & EQUIPMENT', subcategory: 'TOOLS' }],
    ['EQUIPMENT', { category: 'TOOLS & EQUIPMENT' }],
    ['BRUSHES',   { category: 'TOOLS & EQUIPMENT', subcategory: 'BRUSHES' }],
  ])
  
  const isBlockedImagePath = (imagePath = '') => {
    const normalizedPath = normalizeCatalogueToken(imagePath)
    if (!normalizedPath) return false

    return Array.from(blockedCategoryTokens).some((token) => normalizedPath.includes(`/${token}/`) || normalizedPath.endsWith(`/${token}`) || normalizedPath.includes(token))
  }

  const uniqueImagePaths = new Set(
    Object.values(payload)
      .filter((value) => typeof value === 'string')
      .map((value) => String(value).trim())
      .filter((value) => value.includes('/gelitup-content/product-images/'))
      .filter((value) => !isCategoryHeroAssetPath(value))
      .filter((value) => !isBlockedImagePath(value))
  )

  const alternateGalleryImageMap = new Map()
  Array.from(uniqueImagePaths).forEach((imagePath) => {
    const baseImagePath = getAlternateGalleryBaseImagePath(imagePath)
    if (!baseImagePath || !uniqueImagePaths.has(baseImagePath)) return
    const galleryImages = alternateGalleryImageMap.get(baseImagePath) || []
    if (!galleryImages.includes(imagePath)) galleryImages.push(imagePath)
    alternateGalleryImageMap.set(baseImagePath, galleryImages)
    uniqueImagePaths.delete(imagePath)
  })

  // Merge alternate product images — these are extra angles/photos of the same product
  const duplicateImagePaths = new Set([
    '/gelitup-content/product-images/NAIL ART/CUSHION GEL/cushion sponge 2.webp',
  ])
  duplicateImagePaths.forEach(p => uniqueImagePaths.delete(p))

  const grouped = new Map()

  uniqueImagePaths.forEach((imagePath) => {
    const afterRoot = imagePath.split('/gelitup-content/product-images/')[1] || ''
    const segments = afterRoot.split('/').filter(Boolean)
    const sourceCategory = segments[0] || 'Other'
    let category = sourceCategory
    
    // Apply category remapping (e.g., BY THE OCEAN ? COLORS)
    const remappedCategory = categoryRemapping.get(category)
    let isRemapped = !!remappedCategory
    let fixedSubcategory = null
    if (remappedCategory) {
      if (typeof remappedCategory === 'string') {
        category = remappedCategory
      } else {
        // Object form: { category, subcategory } — subcategory is fixed regardless of folder depth
        category = remappedCategory.category
        fixedSubcategory = remappedCategory.subcategory
      }
    }

    // Path-based override: BASES/BRUSH ON BUILDER/* → BUILDER GEL SYSTEMS
    // (images are stored under BASES/ but the product belongs in Builder Gel Systems)
    if (!isRemapped && category === 'BASES' && (segments[1] || '').toUpperCase() === 'BRUSH ON BUILDER') {
      category = 'BUILDER GEL SYSTEMS'
      isRemapped = true
    }
    
    // Determine subcategory based on folder structure
    let subcategory
    if (fixedSubcategory) {
      // Fixed subcategory override — all items in this folder share one subcategory pill
      subcategory = fixedSubcategory
    } else if (isRemapped) {
      if (segments.length > 2) {
        // For remapped categories with real subfolders, use the path between root and filename
        // e.g., BUILDER GEL/3INI BUILDER/item.jpg → "3INI BUILDER"
        subcategory = segments.slice(1, -1).join(' / ') || sourceCategory
      } else {
        // For remapped categories with files directly under root, keep root as subcategory
        // e.g., CREME DE LA CREME/item.jpg → "CREME DE LA CREME"
        subcategory = sourceCategory
      }
    } else if (category === 'COLORS' && segments.length > 3) {
      // Deep path: COLORS/SOLID GEL POLISH/Red/img.jpg ? subcategory='SOLID GEL POLISH', family stored on item
      subcategory = segments[1]
    } else if (category === 'COLORS' && segments.length > 2) {
      // Standard: COLORS/CAT EYE/img.jpg ? subcategory='CAT EYE'
      // NUDE, FRENCH, PASTEL, RONE (GIUP1) belong under Solid Gel Polish
      const folderToken = (segments[segments.length - 2] || 'General').toUpperCase()
      subcategory = ['FRENCH', 'NUDE', 'PASTEL', 'RONE'].includes(folderToken)
        ? 'SOLID GEL POLISH'
        : (segments[segments.length - 2] || 'General')
    } else if (segments.length > 2) {
      // For other categories with deep nesting, join middle segments
      subcategory = segments.slice(1, -1).join(' / ')
    } else {
      // Simple structure: just use first subfolder or 'General'
      subcategory = segments[1] || 'General'
    }

    const categoryBucket = grouped.get(category) || new Map()
    const subcategoryItems = categoryBucket.get(subcategory) || []

    const rawFolder = (segments[segments.length - 2] || '').toUpperCase()
    const solidGelFlatFolders = { NUDE: 'Nude', FRENCH: 'French', PASTEL: 'Pastel', RONE: 'GIUP1' }
    subcategoryItems.push({
      imageUrl: imagePath,
      code: preferredSourceKeyByImagePath.get(imagePath) || formatCatalogueItemName(afterRoot),
      name: preferredDisplayNameByImagePath.get(imagePath) || canonicalDisplayNameByImagePath.get(imagePath) || formatCatalogueItemName(afterRoot),
      galleryImages: alternateGalleryImageMap.get(imagePath) || [],
      colorFamily: category === 'COLORS'
        ? segments.length > 3
          ? segments[2]
          : solidGelFlatFolders[rawFolder] || undefined
        : undefined,
    })

    categoryBucket.set(subcategory, subcategoryItems)
    grouped.set(category, categoryBucket)

    // Mirror Powder Top Coat also appears in Nail Art / Mirror Powders (in addition to Tops)
    if (/mirror.powder.top.coat|mirror.top.coat/i.test(imagePath) && category !== 'NAIL ART') {
      const nailArtBucket = grouped.get('NAIL ART') || new Map()
      const mirrorItems = nailArtBucket.get('MIRROR POWDERS') || []
      const candidateName = (preferredDisplayNameByImagePath.get(imagePath) || canonicalDisplayNameByImagePath.get(imagePath) || formatCatalogueItemName(afterRoot)).toUpperCase()
      const alreadyPresent = mirrorItems.some(i =>
        i.imageUrl === imagePath || i.name.toUpperCase() === candidateName
      )
      if (!alreadyPresent) {
        mirrorItems.push({
          imageUrl: imagePath,
          code: preferredSourceKeyByImagePath.get(imagePath) || formatCatalogueItemName(afterRoot),
          name: preferredDisplayNameByImagePath.get(imagePath) || canonicalDisplayNameByImagePath.get(imagePath) || formatCatalogueItemName(afterRoot),
          galleryImages: alternateGalleryImageMap.get(imagePath) || [],
          colorFamily: undefined,
        })
      }
      nailArtBucket.set('MIRROR POWDERS', mirrorItems)
      grouped.set('NAIL ART', nailArtBucket)
    }
  })

  // Copy 2026 NEW! 5-in-1 Superior Base items (Serenity/Blue variants) into the main BASES section
  // so all 5-in-1 variants appear together under Bases & Tops
  const newProductsMap = grouped.get('2026 NEW!')
  if (newProductsMap) {
    const newSerenityItems = newProductsMap.get('5-in-1 Superior Base') || []
    if (newSerenityItems.length > 0) {
      const basesMap = grouped.get('BASES') || new Map()
      const existing5in1 = basesMap.get('5IN1 SUPERIOR BASE') || []
      const existingUrls = new Set(existing5in1.map(i => i.imageUrl))
      newSerenityItems.forEach(item => {
        if (!existingUrls.has(item.imageUrl)) existing5in1.push({ ...item })
      })
      basesMap.set('5IN1 SUPERIOR BASE', existing5in1)
      grouped.set('BASES', basesMap)
    }

    const builderSystemsMap = grouped.get('BUILDER GEL SYSTEMS') || new Map()
    const glitterBuilderItems = Array.from(builderSystemsMap.entries())
      .filter(([subcategoryName]) => normalizeCatalogueToken(subcategoryName).includes('GLITTER 3 IN 1 BUILDER GEL'))
      .flatMap(([, items]) => items)

    if (glitterBuilderItems.length > 0) {
      const glitterItems = newProductsMap.get('3-in-1 Glitters') || []
      const existingUrls = new Set(glitterItems.map((item) => item.imageUrl))

      glitterBuilderItems.forEach((item) => {
        if (!existingUrls.has(item.imageUrl)) {
          glitterItems.push({ ...item })
          existingUrls.add(item.imageUrl)
        }
      })

      newProductsMap.set('3-in-1 Glitters', glitterItems)
      grouped.set('2026 NEW!', newProductsMap)
    }
  }

  return Array.from(grouped.entries())
    .map(([category, subcategoryMap]) => ({
      category,
      subcategories: Array.from(subcategoryMap.entries())
        .map(([name, items]) => ({
          name,
          items: applyManualCatalogueOrder(
            mergeAlternateGalleryItems(items),
            manualRuleIndex.get(`${category}::${name}`) || null,
          ),
        }))
        .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base', numeric: true })),
    }))
    .sort((a, b) => a.category.localeCompare(b.category, undefined, { sensitivity: 'base', numeric: true }))
}

