function isColorsCategoryName(categoryName = '') {
  return normalizeCatalogueToken(categoryName).includes('COLOR')
}

function toTitleCaseLabel(value = '') {
  const text = String(value || '').trim()
  if (!text) return ''

  const minorWords = new Set(['and', 'or', 'to', 'of', 'the', 'a', 'an', 'in', 'on', 'for', 'by', 'with'])

  return text
    .toLowerCase()
    .split(/\s+/)
    .map((word, index) => {
      const parts = word.split('-')
      return parts
        .map((part) => {
          if (!part) return part
          if (minorWords.has(part) && index !== 0) return part
          return part.charAt(0).toUpperCase() + part.slice(1)
        })
        .join('-')
    })
    .join(' ')
}

/**
 * Maps internal category token names to SEO-friendly display labels.
 * Used in headings, alt text, and structured data.
 */
function formatCategoryDisplayName(categoryName = '') {
  const normalized = normalizeCatalogueToken(categoryName)
  if (normalized.includes('COLOR') || normalized.includes('COLOUR')) return 'Gel Polish'
  if (normalized === 'BUILDER GEL SYSTEMS') return 'Builder Gel Systems'
  if (normalized === 'BUILDER GEL') return 'Builder Gel'
  if (normalized === 'BASES') return 'Base Coats'
  if (normalized === 'TOPS') return 'Top Coats'
  if (normalized === 'MULTIMIX') return 'Synthogel Multimix'
  if (normalized === 'NAIL PREPARATIONS') return 'Nail Preparations'
  if (normalized === 'NAIL ART') return 'Nail Art'
  if (normalized === 'CONSUMABLES') return 'Consumables'
  if (normalized.includes('NAIL HAND')) return 'Nail, Hand & Foot Care'
  if (normalized === 'TOOLS') return 'Tools'
  if (normalized === 'EQUIPMENT') return 'Equipment'
  if (normalized === 'BRUSHES') return 'Brushes'
  if (normalized === 'LINE-IT-UP' || normalized === 'LINE IT UP') return 'Line It Up'
  return toTitleCaseLabel(categoryName)
}

/**
 * Returns a keyword-rich heading label for the active subcategory context.
 * Used in H3 headings and aria context within the category detail panel.
 */
function formatSubcategoryHeadingLabel(subcategoryName = '', categoryName = '') {
  const normalizedSub = normalizeCatalogueToken(subcategoryName)
  const normalizedCat = normalizeCatalogueToken(categoryName)
  if (normalizedSub === 'CAT EYE' && normalizedCat.includes('COLOR')) return 'Cat Eye Gel Polish'
  if (normalizedSub === '5IN1 SUPERIOR BASE') return '5-in-1 Base Coat'
  if (normalizedSub === 'PREMIUM BUILDER') return 'Fiberglass Builder Gel'
  if (normalizedSub === 'BRUSH ON BUILDER') return 'Brush On Builder (BIAB)'
  if (normalizedSub === 'SOLID GEL POLISH') return 'Solid Gel Polish'
  if (normalizedSub === 'CLASSIC TOP COATS') return 'Classic Top Coats'
  if (normalizedSub === '3INI BUILDER') return '3-IN-1 Builder Gel'
  return formatSubcategoryDisplayName(subcategoryName, categoryName)
}

function formatSubcategoryDisplayName(subcategoryName = '', categoryName = '') {
  // Transform specific subcategory names for display
  const normalized = normalizeCatalogueToken(subcategoryName)

  if (normalized === 'ALL') {
    const catToken = normalizeCatalogueToken(categoryName)
    return catToken.includes('COLOR') ? 'All Colors' : 'All Items'
  }
  
  // Color subcategories
  if (normalized === 'RONE') return 'GIUP1'
  if (normalized === 'CAT EYE') return 'Cat Eye'
  if (normalized === 'FRENCH') return 'French'
  if (normalized === 'GLITTERS') return 'Glitters'
  if (normalized === 'JELLY') return 'Jelly'
  if (normalized === 'METALLIC COLLECTION') return 'Metallic Collection'
  if (normalized === 'NEW YORK') return 'New York'
  if (normalized === 'NUDE') return 'Nude'
  if (normalized === 'PMA') return 'PMA'
  if (normalized === 'SHIMMER COLORS') return 'Shimmer Colors'
  if (normalized === 'SNOWFLAKE') return 'Snowflake'
  if (normalized === 'SOLID GEL POLISH') return 'Solid Gel Polish'
  if (normalized === 'SPIX & SPEX' || normalized === 'SPIX  SPEX') return 'Spix & Spex'
  if (normalized === 'THERMO') return 'Thermo'
  if (normalized === 'TUTTI FRUTTI GLASS') return 'Tutti Frutti Glass'
  if (normalized === 'GLASS EFFECT') return 'Glass Effect'
  if (normalized.includes('3INI BUILDER') && normalized.includes('GLITTER 3 IN 1 BUILDER GEL')) {
    return '3-IN-1 Builder Gel / Glitter 3-IN-1 Builder Gel'
  }
  if (normalized.includes('PREMIUM BUILDER') && normalized.includes('40G')) {
    return '3-IN-1 Premium Builder Gel / 40g'
  }
  if (normalized.includes('PREMIUM BUILDER') && normalized.includes('20G')) {
    return '3-IN-1 Premium Builder Gel / 20g'
  }

  // Builder Gel Systems subcategories
  if (normalized === '3INI BUILDER') return '3-IN-1 Builder Gel'
  if (normalized === 'PREMIUM BUILDER') return '3-IN-1 Premium Builder Gel'
  if (normalized === 'LIQUID POLYGEL') return 'Liquid Polygel'
  if (normalized === 'COMPETE') return 'Compete Acrylic'
  if (normalized === 'MULTIMIX' || normalized === '30 ML' || normalized === '30GR' || normalized === '30G') return 'Multimix 30g'
  if (normalized === '60 ML' || normalized === '60GR' || normalized === '60G') return 'Multimix 60g'
  if (normalized === 'CDC' || normalized === 'CREME DE LA CREME') return 'Crème De La Crème'
  
  // Bases subcategories
  if (normalized === '5IN1 SUPERIOR BASE') return '5-in-1 Superior Base'
  if (normalized === 'BRUSH ON BUILDER') return 'Brush On Builder (BIAB)'
  if (normalized === 'FLEXI BASE') return 'Flexi Base'
  if (normalized === 'SUPERBOND') return 'Superbond'
  
  // Tops subcategories
  if (normalized === 'CLASSIC TOP COATS') return 'Classic Top Coats'
  if (normalized === 'EFFECT TOPS') return 'Effect Tops'
  if (normalized === 'SHIMMER TOP') return 'Shimmer Top'
  if (normalized === 'SPOT MY TOPS') return 'Spot My Tops'
  
  // Consumables subcategories
  if (normalized === 'CREAMS AND SCRUBS') return 'Creams and Scrubs'
  if (normalized === 'CUTICLE OILS -REMOVERS' || normalized === 'CUTICLE OILS REMOVERS') return 'Cuticle Oils & Removers'
  if (normalized === 'NAIL FILES') return 'Nail Files'
  if (normalized === 'NAIL TIPS') return 'Nail Tips'
  if (normalized === 'DUAL FORMS') return 'Dual Forms'
  if (normalized === 'SOAK OFF GEL TIPS') return 'Soak Off Gel Tips'
  if (normalized === 'SUPER FLEXIBLE TIPS') return 'Super Flexible Tips'
  if (normalized === 'NAIL FORMS') return 'Nail Forms'
  // Nail Hand & Foot Care subcategories
  if (normalized === 'NAIL HAND FOOT CARE') return 'Nail, Hand & Foot Care'
  
  // Nail Art subcategories
  if (normalized === 'CUSHION GEL') return 'Cushion Gel'
  if (normalized === 'GLITTER EFFECTS POWEDER' || normalized === 'GLITTER EFFECTS POWDER') return 'Glitter Effects Powder'
  if (normalized === 'MARBLE INK') return 'Marble Ink'
  if (normalized === 'MIRROR POWDERS') return 'Mirror Powders'
  if (normalized === 'STICKERS') return 'Stickers'
  if (normalized === 'GIUP BLOSSOM WEBP') return 'GIUP Blossom'
  
  // Packages
  if (normalized === 'STUDIO ELITE') return 'Studio Elite'
  if (normalized === 'BOUTIQUE') return 'B2B Salon'
  if (normalized === 'PROFESSIONAL') return 'Professional'
  if (normalized === 'AUTHORITY') return 'Authority'
  
  // Strip image file extensions and convert underscores ? spaces before title-casing
  const cleanName = subcategoryName
    .replace(/\.(jpe?g|png|webp|gif|svg|avif|bmp|tiff?)$/i, '')
    .replace(/_/g, ' ')
  return toTitleCaseLabel(cleanName)
}

function buildCategoryHeroImageCandidates(categoryName = '', fallbackImageUrl = '') {
  const normalizedCategory = normalizeCatalogueToken(categoryName)
  const tokens = normalizedCategory.split(' ').filter(Boolean)
  const slug = tokens.map((token) => token.toLowerCase()).join('-')
  const baseNames = new Set()

  if (slug) {
    baseNames.add(slug)
  }

  tokens.forEach((token) => {
    baseNames.add(token.toLowerCase())
  })

  if (baseNames.has('colours')) baseNames.add('colors')
  if (baseNames.has('colors')) baseNames.add('colours')

  const extensions = ['jpg', 'jpeg', 'png', 'webp']
  const candidates = []

  // Prioritize catalog-heroes (centralized hero images folder)
  baseNames.forEach((baseName) => {
    extensions.forEach((extension) => {
      candidates.push(`/gelitup-content/catalog-heroes/${baseName}.hero.image.${extension}`)
    })
  })

  // Fallback to product-images category folders
  const encodedCategory = encodeURIComponent(String(categoryName || '').trim())
  if (encodedCategory) {
    extensions.forEach((extension) => {
      candidates.push(`/gelitup-content/product-images/${encodedCategory}/hero.image.${extension}`)
    })
  }

  if (fallbackImageUrl) {
    candidates.push(fallbackImageUrl)
  }

  return Array.from(new Set(candidates))
}

function flattenSectionItems(section) {
  if (!section) return []

  return section.subcategories.flatMap((subcategory) =>
    subcategory.items.map((item) => ({
      ...item,
      subcategory: subcategory.name,
      colorFamilyKey: resolveColorFamilyKey(item.name),
    })),
  )
}

function getSubcategoryProductInformation(categoryName = '', subcategoryName = '') {
  const categoryToken = normalizeCatalogueToken(categoryName)
  const subcategoryToken = normalizeCatalogueToken(subcategoryName)
  if (!categoryToken) return null

  // Exact subcategory match first, then category-level fallback (subcategory === 'ALL')
  const exactMatch = (
    PRODUCT_INFORMATION_BY_SUBCATEGORY[`${categoryToken}::${subcategoryToken}`] ||
    PRODUCT_INFORMATION_BY_SUBCATEGORY[`${categoryToken}::ALL`] ||
    null
  )
  if (exactMatch) return exactMatch

  if (!subcategoryToken) return null

  const fuzzyMatchKey = Object.keys(PRODUCT_INFORMATION_BY_SUBCATEGORY).find((key) => {
    const [rawCategory = '', rawSubcategory = ''] = String(key || '').split('::')
    if (normalizeCatalogueToken(rawCategory) !== categoryToken) return false
    const keySubcategoryToken = normalizeCatalogueToken(rawSubcategory)
    if (!keySubcategoryToken) return false
    return keySubcategoryToken === subcategoryToken
      || (subcategoryToken.length >= 5 && (
        keySubcategoryToken.includes(subcategoryToken)
        || subcategoryToken.includes(keySubcategoryToken)
      ))
  })

  return fuzzyMatchKey ? PRODUCT_INFORMATION_BY_SUBCATEGORY[fuzzyMatchKey] : null
}

// Flexible lookup for the B2B catalog view where category names come from WooCommerce/Supabase
// and may not exactly match the image-folder-based keys.
function getB2BCategoryDescription(categoryName = '') {
  if (!categoryName) return null
  const token = normalizeCatalogueToken(categoryName)
  if (!token) return null

  // 1. Direct ::ALL match (e.g., category stored as 'MULTIMIX' ? 'MULTIMIX::ALL')
  const direct = PRODUCT_INFORMATION_BY_SUBCATEGORY[`${token}::ALL`]
  if (direct) return direct

  // 2. Match as subcategory part of any key (e.g., 'MULTIMIX' ? 'BUILDER GEL SYSTEMS::MULTIMIX')
  const subKey = Object.keys(PRODUCT_INFORMATION_BY_SUBCATEGORY).find((key) => {
    const parts = key.split('::')
    if (parts.length < 2) return false
    const subToken = normalizeCatalogueToken(parts[1])
    return subToken === token || (token.length >= 5 && (subToken.includes(token) || token.includes(subToken)))
  })
  if (subKey) return PRODUCT_INFORMATION_BY_SUBCATEGORY[subKey]

  // 3. First match where category part matches (e.g., 'NAIL ART' ? 'NAIL ART::CUSHION GEL')
  const catKey = Object.keys(PRODUCT_INFORMATION_BY_SUBCATEGORY).find((key) => {
    const catPart = normalizeCatalogueToken((key.split('::')[0]) || '')
    return catPart === token
  })
  return catKey ? PRODUCT_INFORMATION_BY_SUBCATEGORY[catKey] : null
}

