function ExternalRedirect({ to }) {
  useEffect(() => { window.location.href = to }, [to])
  return null
}

function ScrollToTopOnRouteChange() {
  const location = useLocation()

  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: 'auto' })
  }, [location.pathname])

  // fires after React renders each route — signals prerenderer to capture the HTML
  useEffect(() => {
    document.dispatchEvent(new Event('gelitup-prerender-ready'))
  }, [location.pathname])

  return null
}

function LegacyMirrorPage({ pagePath }) {
  const normalizedPath = pagePath.startsWith('/') ? pagePath : `/${pagePath}`
  const targetUrl = `${LEGACY_SITE_ORIGIN}${normalizedPath}`

  return (
    <section className="space-y-3">
      <div className="rounded-2xl border border-slate-200 bg-white p-4 sm:p-5">
        <p className="text-xs uppercase tracking-[0.16em] text-slate-500">Legacy Mirror Mode</p>
        <p className="mt-1 text-sm text-slate-600">
          Live embedded page from {targetUrl}. Disable `VITE_ENABLE_LEGACY_MIRROR` to switch back to migrated React layouts.
        </p>
      </div>

      <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white">
        <iframe
          src={targetUrl}
          title={`Legacy mirror ${normalizedPath}`}
          className="h-[76vh] w-full"
          loading="lazy"
          referrerPolicy="no-referrer-when-downgrade"
        />
      </div>
    </section>
  )
}

function useSnapshotPages() {
  const [snapshotPages, setSnapshotPages] = useState([])
  const [mediaBySourceUrl, setMediaBySourceUrl] = useState({})
  const [isLoading, setIsLoading] = useState(true)
  const [errorMessage, setErrorMessage] = useState('')

  useEffect(() => {
    let isMounted = true

    const loadSnapshot = async () => {
      setIsLoading(true)
      setErrorMessage('')

      try {
        const [snapshotResponse, mediaResponse] = await Promise.all([
          fetch('/gelitup-content/pages.json'),
          fetch('/gelitup-media/manifest.json'),
        ])

        if (!snapshotResponse.ok) {
          throw new Error(`Content snapshot unavailable (${snapshotResponse.status})`)
        }

        const snapshotPayload = await snapshotResponse.json()
        const mediaPayload = mediaResponse.ok ? await mediaResponse.json() : { items: [] }

        if (!isMounted) return

        setSnapshotPages(Array.isArray(snapshotPayload?.pages) ? snapshotPayload.pages : [])

        const mediaMap = {}
        for (const item of mediaPayload?.items || []) {
          if (item?.sourceUrl && item?.localPath) {
            mediaMap[item.sourceUrl] = item.localPath
          }
        }

        setMediaBySourceUrl(mediaMap)
      }
      catch (error) {
        if (!isMounted) return
        setErrorMessage(error instanceof Error ? error.message : 'Unable to load snapshot pages.')
      }
      finally {
        if (isMounted) {
          setIsLoading(false)
        }
      }
    }

    void loadSnapshot()

    return () => {
      isMounted = false
    }
  }, [])

  return { snapshotPages, mediaBySourceUrl, isLoading, errorMessage }
}

function BaselinePagesIndex() {
  const { snapshotPages, isLoading, errorMessage } = useSnapshotPages()

  return (
    <section className="space-y-4">
      <div className="rounded-2xl border border-slate-200 bg-white p-6">
        <h2 className="text-2xl font-semibold text-slate-900">Imported Page Baseline</h2>
        <p className="mt-2 text-sm text-slate-600">
          Page-by-page baseline imported from gelitup.com snapshot. Open any page below and start editing progressively.
        </p>
      </div>

      {isLoading && <p className="text-sm text-slate-600">Loading snapshot pages...</p>}
      {!isLoading && errorMessage && <p className="text-sm text-rose-600">{errorMessage}</p>}

      {!isLoading && !errorMessage && (
        <div className="grid gap-3 sm:grid-cols-2">
          {snapshotPages.map((page) => (
            <NavLink
              key={page.url}
              to={`/baseline/${page.slug}`}
              className="rounded-xl border border-slate-200 bg-white p-4 transition hover:border-slate-300"
            >
              <p className="text-sm font-semibold text-slate-900">{page.title || page.slug}</p>
              <p className="mt-1 text-xs text-slate-500">/{page.slug}</p>
              <p className="mt-2 text-xs text-slate-600">
                {page.paragraphs?.[0]?.slice(0, 140) || 'No paragraph snapshot available.'}
              </p>
              <p className="mt-3 text-xs font-semibold text-slate-800">
                Dedicated page route: /pages/{page.slug}
              </p>
            </NavLink>
          ))}
        </div>
      )}
    </section>
  )
}

function BaselinePageView() {
  const { slug } = useParams()
  const { snapshotPages, mediaBySourceUrl, isLoading, errorMessage } = useSnapshotPages()

  const page = useMemo(
    () => snapshotPages.find((candidate) => candidate.slug === slug),
    [slug, snapshotPages],
  )

  const previewMedia = useMemo(() => {
    if (!page?.mediaRefs?.length) return []

    return page.mediaRefs.slice(0, 8).map((sourceUrl) => ({
      sourceUrl,
      displayUrl: mediaBySourceUrl[sourceUrl] || sourceUrl,
    }))
  }, [mediaBySourceUrl, page])

  if (isLoading) {
    return <p className="text-sm text-slate-600">Loading page baseline...</p>
  }

  if (errorMessage) {
    return <p className="text-sm text-rose-600">{errorMessage}</p>
  }

  if (!page) {
    return (
      <section className="space-y-3">
        <p className="text-sm text-slate-600">Page snapshot not found for this slug.</p>
        <NavLink to="/baseline" className="inline-flex rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold text-slate-700">
          Back to Baseline List
        </NavLink>
      </section>
    )
  }

  return (
    <section className="space-y-4">
      <div className="rounded-2xl border border-slate-200 bg-white p-6">
        <p className="text-xs uppercase tracking-[0.16em] text-slate-500">Snapshot Page</p>
        <h2 className="mt-2 text-2xl font-semibold text-slate-900">{page.title || page.slug}</h2>
        <p className="mt-2 text-xs text-slate-500">Source: {page.url}</p>
      </div>

      {page.headings?.h1?.length > 0 && (
        <InfoCard title="Primary Headings">
          <ul className="space-y-1">
            {page.headings.h1.map((heading) => <li key={heading}>— {heading}</li>)}
          </ul>
        </InfoCard>
      )}

      {page.headings?.h2?.length > 0 && (
        <InfoCard title="Section Headings">
          <ul className="space-y-1">
            {page.headings.h2.map((heading) => <li key={heading}>— {heading}</li>)}
          </ul>
        </InfoCard>
      )}

      {page.paragraphs?.length > 0 && (
        <InfoCard title="Content Blocks">
          <div className="space-y-3">
            {page.paragraphs.map((paragraph) => (
              <p key={paragraph} className="text-sm leading-relaxed text-slate-700">{paragraph}</p>
            ))}
          </div>
        </InfoCard>
      )}

      {previewMedia.length > 0 && (
        <InfoCard title="Media Baseline">
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
            {previewMedia.map((item) => {
              const isVideo = item.displayUrl.toLowerCase().includes('.mp4') || item.displayUrl.toLowerCase().includes('.webm')

              return isVideo
                ? (
                  <video key={item.sourceUrl} src={item.displayUrl} className="h-28 w-full rounded-lg object-cover" muted playsInline controls />
                )
                : (
                  <img key={item.sourceUrl} src={item.displayUrl} alt="Page baseline media" className="h-28 w-full rounded-lg object-cover" loading="lazy" />
                )
            })}
          </div>
        </InfoCard>
      )}

      <NavLink to="/baseline" className="inline-flex rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold text-slate-700">
        Back to Baseline List
      </NavLink>
      <NavLink to={`/pages/${slug}`} className="ml-2 inline-flex rounded-lg border border-slate-300 px-3 py-2 text-sm font-semibold text-slate-700">
        Open Dedicated Page Route
      </NavLink>
    </section>
  )
}

function InstagramFeedStrip() {
  useEffect(() => {
    const trySetup = () => {
      try {
        if (window.eapps?.Platform?.setupWidgets) {
          window.eapps.Platform.setupWidgets()
          return true
        }
      } catch (_) { /* not ready */ }
      return false
    }

    if (document.querySelector('script[src*="elfsightcdn.com/platform"]')) {
      if (!trySetup()) {
        let attempts = 0
        const iv = setInterval(() => {
          if (trySetup() || ++attempts >= 30) clearInterval(iv)
        }, 500)
        return () => clearInterval(iv)
      }
      return
    }
    const script = document.createElement('script')
    script.src = 'https://elfsightcdn.com/platform.js'
    script.async = true
    document.body.appendChild(script)
  }, [])

  return (
    <div className="relative left-1/2 right-1/2 -ml-[50vw] -mr-[50vw] w-screen bg-[#F5F5F5] py-8">
      <div className="mx-auto max-w-6xl px-4 sm:px-8">
        <div className="mb-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <svg viewBox="0 0 24 24" className="h-5 w-5" fill="none" xmlns="http://www.w3.org/2000/svg">
              <defs>
                <linearGradient id="ig-grad" x1="0%" y1="100%" x2="100%" y2="0%">
                  <stop offset="0%" stopColor="#f09433" />
                  <stop offset="25%" stopColor="#e6683c" />
                  <stop offset="50%" stopColor="#dc2743" />
                  <stop offset="75%" stopColor="#cc2366" />
                  <stop offset="100%" stopColor="#bc1888" />
                </linearGradient>
              </defs>
              <rect x="2" y="2" width="20" height="20" rx="5" ry="5" stroke="url(#ig-grad)" strokeWidth="2" fill="none" />
              <circle cx="12" cy="12" r="4" stroke="url(#ig-grad)" strokeWidth="2" fill="none" />
              <circle cx="17.5" cy="6.5" r="1" fill="url(#ig-grad)" />
            </svg>
            <span className="text-sm font-bold uppercase tracking-[0.12em] text-[#1A1A1A]">
              @{INSTAGRAM_HANDLE}
            </span>
          </div>
          <a
            href={INSTAGRAM_URL}
            target="_blank"
            rel="noreferrer"
            className="text-xs font-semibold uppercase tracking-widest text-[#D43790] transition hover:text-[#BF3182]"
          >
            Follow Us →
          </a>
        </div>
        <div className="elfsight-app-42ee70be-f926-412b-b52f-47a51f35a691" data-elfsight-app-lazy />
      </div>
    </div>
  )
}

function GoogleReviewsStrip() {
  const [reviews, setReviews] = useState([])
  const [summary, setSummary] = useState(null) // { rating, totalRatings, placeUrl }
  const [status, setStatus] = useState('loading') // 'loading' | 'ok' | 'error'

  useEffect(() => {
    let mounted = true
    const load = async () => {
      try {
        const res = await fetch('/.netlify/functions/google-reviews')
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        const data = await res.json()
        if (mounted) {
          const reviewList = data.reviews || []
          setSummary({ rating: data.rating, totalRatings: data.totalRatings, placeUrl: data.placeUrl })
          setReviews(reviewList)
          setStatus(reviewList.length > 0 ? 'ok' : 'error')
        }
      }
      catch {
        if (mounted) setStatus('error')
      }
    }
    load()
    return () => { mounted = false }
  }, [])

  if (status === 'error' || (status !== 'loading' && reviews.length === 0)) return null

  const StarRating = ({ value }) => {
    const full = Math.floor(value)
    const half = value - full >= 0.5
    return (
      <span className="flex items-center gap-0.5" aria-label={`${value} out of 5 stars`}>
        {Array.from({ length: 5 }).map((_, i) => (
          <svg key={i} viewBox="0 0 20 20" className={`h-4 w-4 ${i < full ? 'fill-yellow-400' : (i === full && half ? 'fill-yellow-300' : 'fill-white/20')}`} xmlns="http://www.w3.org/2000/svg">
            <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118l-2.8-2.034c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
          </svg>
        ))}
      </span>
    )
  }

  return (
    <div className="relative left-1/2 right-1/2 -ml-[50vw] -mr-[50vw] w-screen bg-[#0F0F0F] py-8">
      <div className="mx-auto max-w-6xl px-4 sm:px-8">
        <div className="mb-5 flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-3">
            <svg viewBox="0 0 24 24" className="h-6 w-6 shrink-0" xmlns="http://www.w3.org/2000/svg">
              <path d="M12 2C6.477 2 2 6.477 2 12s4.477 10 10 10 10-4.477 10-10S17.523 2 12 2z" fill="#4285F4" />
              <path d="M17.64 12.204c0-.379-.034-.743-.096-1.093H12v2.068h3.167a2.71 2.71 0 01-1.175 1.777v1.477h1.903c1.113-1.025 1.756-2.535 1.756-4.23z" fill="#4285F4" />
              <path d="M12 18c1.59 0 2.923-.527 3.896-1.427l-1.902-1.477c-.528.354-1.203.563-1.994.563-1.535 0-2.835-1.037-3.299-2.43H6.735v1.526A5.997 5.997 0 0012 18z" fill="#34A853" />
              <path d="M8.701 13.23A3.612 3.612 0 018.5 12c0-.425.073-.838.201-1.23V9.244H6.735A5.997 5.997 0 006 12c0 .967.232 1.88.735 2.756l1.966-1.526z" fill="#FBBC05" />
              <path d="M12 8.14c.865 0 1.64.297 2.25.882l1.688-1.688C14.922 6.342 13.588 5.75 12 5.75A5.997 5.997 0 006.735 9.244l1.966 1.526C9.165 9.177 10.465 8.14 12 8.14z" fill="#EA4335" />
            </svg>
            <div>
              <p className="text-sm font-bold uppercase tracking-[0.1em] text-white">Google Reviews</p>
              {summary && (
                <div className="mt-0.5 flex items-center gap-2">
                  <StarRating value={summary.rating} />
                  <span className="text-xs text-white/60">{summary.rating?.toFixed(1)} · {summary.totalRatings?.toLocaleString()} reviews</span>
                </div>
              )}
            </div>
          </div>
          {summary?.placeUrl && (
            <a
              href={summary.placeUrl}
              target="_blank"
              rel="noreferrer"
              className="text-xs font-semibold uppercase tracking-widest text-[#D43790] transition hover:text-fuchsia-300"
            >
              Write a Review →
            </a>
          )}
        </div>

        {status === 'loading'
          ? (
            <div className="flex gap-4 overflow-hidden">
              {Array.from({ length: 3 }).map((_, i) => (
                <div key={i} className="h-44 w-72 flex-shrink-0 animate-pulse rounded-xl bg-white/10" />
              ))}
            </div>
            )
          : (
            <div className="scrollbar-hide -mx-4 flex snap-x snap-mandatory gap-4 overflow-x-auto px-4 pb-2 sm:-mx-8 sm:px-8">
              {reviews.map((review, i) => (
                <div
                  key={i}
                  className="w-[min(72vw,288px)] flex-shrink-0 snap-start rounded-xl border border-white/10 bg-white/5 p-4 sm:w-72"
                >
                  <div className="flex items-center gap-2">
                    {review.authorPhoto
                      ? <img src={review.authorPhoto} alt={review.author} className="h-8 w-8 rounded-full object-cover" loading="lazy" referrerPolicy="no-referrer" />
                      : <div className="flex h-8 w-8 items-center justify-center rounded-full bg-fuchsia-600 text-xs font-bold text-white">{review.author?.charAt(0)}</div>
                    }
                    <div className="flex-1 overflow-hidden">
                      <p className="truncate text-xs font-semibold text-white">{review.author}</p>
                      <p className="text-[10px] text-white/40">{review.relativeTime}</p>
                    </div>
                  </div>
                  <StarRating value={review.rating} />
                  <p className="mt-2 line-clamp-5 text-xs leading-relaxed text-white/75">{review.text}</p>
                </div>
              ))}
            </div>
            )}
      </div>
    </div>
  )
}

